import React, { useEffect, useState } from 'react';
import Login from './components/Login';
import Register from './components/Register';
import ProductList from './components/ProductList';
import Cart from './components/Cart';
import { fetchProducts } from './api';

export default function App() {
  const [page, setPage] = useState('products'); // 'login','register','cart'
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [loggedIn, setLoggedIn] = useState(!!localStorage.getItem('token'));

  useEffect(() => {
    fetchProducts().then(setProducts).catch(err => console.error('fetchProducts', err));
  }, []);

  function addToCart(product) {
    setCart(prev => {
      const found = prev.find(p => p.productId === product.id);
      if (found) return prev.map(p => p.productId === product.id ? {...p, quantity: p.quantity + 1} : p);
      return [...prev, { productId: product.id, name: product.name, price: product.price, quantity: 1}];
    });
  }

  function removeFromCart(productId) {
    setCart(prev => prev.filter(p => p.productId !== productId));
  }

  function clearCart() { setCart([]); }

  function logout() {
    localStorage.removeItem('token');
    setLoggedIn(false);
    setPage('products');
  }

  return (
    <div className="container">
      <header className="header">
        <h1>E-Commerce</h1>
        <nav>
          <button onClick={() => setPage('products')}>Products</button>
          {!loggedIn && <button onClick={() => setPage('login')}>Login</button>}
          {!loggedIn && <button onClick={() => setPage('register')}>Register</button>}
          <button onClick={() => setPage('cart')}>Cart ({cart.reduce((s,i)=>s+i.quantity,0)})</button>
          {loggedIn && <button onClick={logout}>Logout</button>}
        </nav>
      </header>

      <main>
        {page === 'login' && <Login onLogin={() => { setLoggedIn(true); setPage('products'); }} />}
        {page === 'register' && <Register onRegister={() => setPage('login')} />}
        {page === 'products' && <ProductList products={products} onAdd={addToCart} />}
        {page === 'cart' && <Cart cart={cart} setCart={setCart} onOrderPlaced={clearCart} />}
      </main>
    </div>
  );
}
